import math, heapq, sys, time, json
sys.path.insert(0, '/app')
from lightlag_client import connect
from lightlag_surface import Surface, drive as sdrive, PHYSICS, TERRAIN_CODES

def log(*a):
    print(*a, flush=True)

PASS_T = 0.25
GAIN = PHYSICS['slip_grade_gain']
COSTM = PHYSICS['drive_cost_per_wheel_m']


class Mission:
    def __init__(self, tools):
        self.tools = tools
        self.rules = tools.rules()
        self.D = self.rules['delay_ticks']
        self.T = self.rules['max_ticks']
        w = tools.map()
        self.mission = w['mission']
        self.cell = w['cell_m']
        self.S = Surface(w['cell_m'], w['elevation_cm'], w['terrain'])
        self.base = tuple(w['base'])
        self.slip = {k: (v[0] + v[1]) / 2 for k, v in PHYSICS['slip_base_ranges'].items()}
        self.slip_obs = {k: [] for k in self.slip}
        self.targets = {}
        self.update_targets(w)
        self.build_graph()
        self.fwd = {}
        self.rev = {}
        self.sampled = set()
        self.pending = {}   # tid -> exec tick of sample
        self.est = {0: self.base}
        self.cmds = {}
        self.route = []
        self.last_plan = -100
        self.need_plan = True
        self.seen_pk = 0
        self.battery = 100.0
        self.bias = 0.0
        log('mission', self.mission, 'base', self.base, 'targets', len(self.targets))

    def update_targets(self, w):
        for t in w['targets']:
            if t['id'] not in self.targets:
                self.targets[t['id']] = t

    # ---------- graph ----------
    def build_graph(self):
        S = self.S
        nx, ny = S.nx - 1, S.ny - 1
        self.nx, self.ny = nx, ny
        h = S.h
        self.hc = [[(h[j][i] + h[j][i + 1] + h[j + 1][i] + h[j + 1][i + 1]) / 4 for i in range(nx)] for j in range(ny)]
        self.ms = [[S.cell_max_slope(i, j) for i in range(nx)] for j in range(ny)]
        ok = [[self.ms[j][i] < PASS_T for i in range(nx)] for j in range(ny)]
        self.ok = ok
        adj = [[] for _ in range(nx * ny)]
        radj = [[] for _ in range(nx * ny)]
        c = self.cell
        for j in range(ny):
            for i in range(nx):
                if not ok[j][i]:
                    continue
                a = j * nx + i
                ter = TERRAIN_CODES[S.codes[j][i]]
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        if di == 0 and dj == 0:
                            continue
                        ii, jj = i + di, j + dj
                        if not (0 <= ii < nx and 0 <= jj < ny) or not ok[jj][ii]:
                            continue
                        if di and dj and not (ok[j][ii] and ok[jj][i]):
                            continue
                        d = c * math.hypot(di, dj)
                        grade = (self.hc[jj][ii] - self.hc[j][i]) / d
                        sl = min(0.9, self.slip[ter] + GAIN[ter] * max(0, grade))
                        pen = 1.0 + 0.6 * max(0, self.ms[j][i] - 0.12)  # prefer gentle
                        cost = d / (5.0 * (1 - sl)) * pen + 0.01 * d * COSTM[ter]
                        b = jj * nx + ii
                        adj[a].append((b, cost))
                        radj[b].append((a, cost))
        self.adj, self.radj = adj, radj

    def dijkstra(self, src, adj):
        dist = [math.inf] * (self.nx * self.ny)
        dist[src] = 0.0
        pq = [(0.0, src)]
        while pq:
            d, a = heapq.heappop(pq)
            if d > dist[a]:
                continue
            for b, c in adj[a]:
                nd = d + c
                if nd < dist[b]:
                    dist[b] = nd
                    heapq.heappush(pq, (nd, b))
        return dist

    def cellof(self, x, y):
        i = min(self.nx - 1, max(0, int(x / self.cell)))
        j = min(self.ny - 1, max(0, int(y / self.cell)))
        return j * self.nx + i

    def near_ok(self, x, y):
        a = self.cellof(x, y)
        i, j = a % self.nx, a // self.nx
        if self.ok[j][i]:
            return a
        best = None
        for r in range(1, 4):
            for di in range(-r, r + 1):
                for dj in range(-r, r + 1):
                    ii, jj = i + di, j + dj
                    if 0 <= ii < self.nx and 0 <= jj < self.ny and self.ok[jj][ii]:
                        cx, cy = (ii + .5) * self.cell, (jj + .5) * self.cell
                        d = math.hypot(cx - x, cy - y)
                        if best is None or d < best[0]:
                            best = (d, jj * self.nx + ii)
            if best:
                return best[1]
        return a

    def key_pos(self, k):
        if k == 'base':
            return self.base
        t = self.targets[k]
        return (t['x'], t['y'])

    def fwd_field(self, k):
        if k not in self.fwd:
            self.fwd[k] = self.dijkstra(self.near_ok(*self.key_pos(k)), self.adj)
        return self.fwd[k]

    def rev_field(self, k):
        if k not in self.rev:
            self.rev[k] = self.dijkstra(self.near_ok(*self.key_pos(k)), self.radj)
        return self.rev[k]

    # ---------- planning ----------
    def tval(self, k, t):
        tg = self.targets[k]
        dl = tg['deadline_tick']
        if dl is None or t <= dl:
            return tg['value']
        return tg['late_value']

    def plan(self, pos, t0):
        cand = [k for k, tg in self.targets.items() if k not in self.sampled and k not in self.pending
                and tg.get('appear_tick', 0) <= t0 + 40]
        startd = self.dijkstra(self.near_ok(*pos), self.adj)
        FUD = 1.12
        def tt(a, b):
            if a == 'S':
                d = startd[self.near_ok(*self.key_pos(b))]
            else:
                d = self.fwd_field(a)[self.near_ok(*self.key_pos(b))]
            return d * FUD + 1.0
        cache = {}
        def T(a, b):
            kk = (a, b)
            if kk not in cache:
                cache[kk] = tt(a, b)
            return cache[kk]
        limit = self.T - 6
        def evalr(r):
            t = t0
            v = 0.0
            prev = 'S'
            for k in r:
                t += T(prev, k)
                at = self.targets[k].get('appear_tick', 0)
                if t < at:
                    t = at
                t += 1
                v += self.tval(k, t)
                prev = k
            t += T(prev, 'base')
            return v, t
        best = None
        for alpha in (0.6, 1.0, 1.5):
            route = []
            v0, e0 = evalr(route)
            if e0 > limit:
                route = []
            rem = [k for k in cand if T('S', k) < 1e8]
            while True:
                bestins = None
                for k in rem:
                    for p in range(len(route) + 1):
                        r2 = route[:p] + [k] + route[p:]
                        v, e = evalr(r2)
                        if e > limit:
                            continue
                        dv = v - v0
                        if dv <= 0:
                            continue
                        dt = max(0.5, e - e0)
                        sc = dv / dt ** alpha
                        if bestins is None or sc > bestins[0]:
                            bestins = (sc, k, p, v, e)
                if not bestins:
                    break
                _, k, p, v0, e0 = bestins
                route.insert(p, k)
                rem.remove(k)
            # 2-opt-ish swap improvement
            improved = True
            while improved:
                improved = False
                for i in range(len(route)):
                    for j in range(i + 2, len(route) + 1):
                        r2 = route[:i] + route[i:j][::-1] + route[j:]
                        v, e = evalr(r2)
                        if e <= limit and (v > v0 + 1e-9 or (v >= v0 - 1e-9 and e < e0 - 0.5)):
                            route, v0, e0 = r2, v, e
                            improved = True
            if best is None or v0 > best[0] + 1e-9 or (abs(v0 - best[0]) < 1e-9 and e0 < best[2]):
                best = (v0, route, e0)
        log(f't={t0} plan value={best[0]:.1f} end={best[2]:.0f} route={best[1]}')
        return best[1]

    # ---------- control ----------
    def predict(self, x, y, h, m):
        r = sdrive(self.S, PHYSICS, x, y, h + self.bias, m, self.slip)
        return r

    def line_ok(self, p, q):
        d = math.hypot(q[0] - p[0], q[1] - p[1])
        n = max(1, int(d / 1.0))
        for s in range(n + 1):
            x = p[0] + (q[0] - p[0]) * s / n
            y = p[1] + (q[1] - p[1]) * s / n
            a = self.cellof(x, y)
            if self.ms[a // self.nx][a % self.nx] > 0.30:
                return False
        return True

    def aim(self, p, goal):
        gpos = self.key_pos(goal)
        if math.hypot(gpos[0] - p[0], gpos[1] - p[1]) < 12 and self.line_ok(p, gpos):
            return gpos, True
        field = self.rev_field(goal)
        a = self.near_ok(*p)
        chain = [a]
        gcell = self.near_ok(*gpos)
        for _ in range(8):
            cur = chain[-1]
            if cur == gcell:
                break
            best = None
            for b, c in self.radj[cur] if False else self.adj[cur]:
                v = c + field[b]
                if best is None or v < best[0]:
                    best = (v, b)
            if best is None or field[best[1]] >= field[cur]:
                break
            chain.append(best[1])
        pts = [((c % self.nx + .5) * self.cell, (c // self.nx + .5) * self.cell) for c in chain]
        if chain[-1] == gcell:
            pts.append(gpos)
        target = pts[min(1, len(pts) - 1)]
        for q in pts[1:]:
            if self.line_ok(p, q):
                target = q
            else:
                break
        if math.hypot(target[0] - p[0], target[1] - p[1]) < 1.0 and len(pts) > 1:
            target = pts[-1]
        return target, target == gpos

    def decide(self, e):
        """command executing at tick e, from est[e-1]"""
        p = self.est[e - 1]
        if self.need_plan or e - self.last_plan >= 15:
            self.route = self.plan(p, e)
            self.last_plan = e
            self.need_plan = False
        while self.route and (self.route[0] in self.sampled or self.route[0] in self.pending):
            self.route.pop(0)
        goal = self.route[0] if self.route else 'base'
        gpos = self.key_pos(goal)
        dg = math.hypot(gpos[0] - p[0], gpos[1] - p[1])
        if goal != 'base' and dg < 1.0 and e >= self.targets[goal].get('appear_tick', 0):
            self.pending[goal] = e
            self.route.pop(0)
            return {'action': 'sample'}, p
        if goal == 'base' and dg < 1.2:
            return {'action': 'wait'}, p
        if self.battery < 8 and goal != 'base':
            return {'action': 'wait'}, p
        q, final = self.aim(p, goal)
        dx, dy = q[0] - p[0], q[1] - p[1]
        dist = math.hypot(dx, dy)
        hd = math.degrees(math.atan2(dy, dx)) - self.bias
        m = 5.0
        if final:
            m = min(5.0, max(0.3, dist))
            # iterate to account for slip
            for _ in range(3):
                r = self.predict(p[0], p[1], hd, m)
                g = math.hypot(r['x'] - p[0], r['y'] - p[1])
                if g < 1e-3:
                    break
                m = min(5.0, max(0.25, m * dist / g))
        r = self.predict(p[0], p[1], hd, m)
        if r['stop'] == 'tilt':
            # try shorter
            m2 = max(0.25, r['wheel'] - 0.5)
            r = self.predict(p[0], p[1], hd, m2)
            m = m2
        return {'action': 'drive', 'heading_deg': round(hd % 360, 2), 'metres': round(m, 2)}, (r['x'], r['y'])

    def process(self, packets):
        for pk in packets:
            if pk.get('mission') != self.mission:
                continue
            k = pk['tick']
            if k <= self.seen_pk:
                continue
            self.seen_pk = k
            self.battery = pk['battery']
            ev = pk.get('events') or []
            if ev:
                log('events', k, ev)
            st = set()
            for s in pk.get('sampled_targets') or []:
                st.add(s if isinstance(s, str) else s.get('id'))
            for tid in st:
                if tid not in self.sampled:
                    log(f'sampled {tid} at <= {k}')
                self.sampled.add(tid)
                self.pending.pop(tid, None)
            for tid, et in list(self.pending.items()):
                if k >= et and tid not in st:
                    log(f'sample of {tid} FAILED (exec {et})')
                    self.pending.pop(tid)
                    self.need_plan = True
            stopped = False
            for e in ev:
                s = json.dumps(e).lower()
                if 'discover' in s:
                    self.need_plan = True
                if 'stop' in s or 'tilt' in s or 'safety' in s:
                    stopped = True
            # slip estimation
            c = self.cmds.get(k)
            if c and c.get('action') == 'drive' and pk['wheel_odometry'] > 0.5 and not stopped:
                ter = pk['terrain']
                p0 = self.est.get(k - 1)
                if p0 and ter in self.slip:
                    _, gx, gy, _ = self.S.sample(*p0)
                    hr = math.radians(c['heading_deg'])
                    grade = gx * math.cos(hr) + gy * math.sin(hr)
                    obs = 1 - pk['visual_odometry'] / pk['wheel_odometry'] - GAIN[ter] * max(0, grade)
                    L = self.slip_obs[ter]
                    L.append(obs)
                    lo, hi = PHYSICS['slip_base_ranges'][ter]
                    if len(L) >= 3:
                        self.slip[ter] = min(hi, max(lo, sum(L) / len(L)))
            rep = pk['position']
            if k not in self.est:
                continue
            ex, ey = self.est[k]
            ix, iy = rep[0] - ex, rep[1] - ey
            if stopped:
                g = 1.0
                for j in list(self.est):
                    if j >= k:
                        self.est[j] = (rep[0], rep[1])
                self.need_plan = True
                continue
            g = 0.25 if math.hypot(ix, iy) < 4 else 0.6
            for j in list(self.est):
                if j >= k:
                    x, y = self.est[j]
                    self.est[j] = (x + g * ix, y + g * iy)

    def run(self):
        tools = self.tools
        t = 0
        while True:
            e = t + self.D + 1
            for j in range(1, e):
                if j not in self.est:
                    self.est[j] = self.est[j - 1]
            if e <= self.T:
                try:
                    cmd, newp = self.decide(e)
                    ack = tools.uplink([cmd])
                    self.cmds[e] = cmd
                    self.est[e] = newp
                except Exception as ex:
                    log('uplink err', ex)
                    self.est[e] = self.est[e - 1]
            out = tools.advance(1)
            t = out['current_tick']
            if out.get('episode_complete') or out.get('campaign_complete') or out.get('mission') != self.mission:
                log('mission end', self.mission, 'sampled', sorted(self.sampled), 'est', self.est.get(self.T), 'batt', self.battery, out.get('campaign_complete'))
                return out
            self.process(out.get('packets') or [])
            if any((json.dumps(p.get('events')).lower().find('discover') >= 0) for p in out.get('packets') or []):
                self.update_targets(tools.map())
            if t % 20 == 0:
                p = self.est.get(t)
                log(f't={t} est={p} batt={self.battery:.1f} slip={ {k: round(v,3) for k,v in self.slip.items()} } route={self.route[:4]}')


def main():
    with connect('http://lightlag:8000/mcp') as tools:
        while True:
            m = Mission(tools)
            out = m.run()
            if out.get('campaign_complete'):
                break
            r = tools.rules()
            if r['campaign']['complete']:
                break
    log('CAMPAIGN DONE')

if __name__ == '__main__':
    main()
